('20000000-0000-4000-8000-000000000005','11111111-1111-4111-8111-111111111111','الباحثون والعملاء','ملفات الباحثين والعملاء، المتطلبات، الميزانية والربط الذكي.',3,5,38,'active',5),
('20000000-0000-4000-8000-000000000006','11111111-1111-4111-8111-111111111111','القروبات والدعوات','قروبات 1–10 أعضاء، الدعوات، الصلاحيات والمخزون المشترك.',4,7,18,'active',6),
('20000000-0000-4000-8000-000000000007','11111111-1111-4111-8111-111111111111','الاشتراكات والدفع','Free / Pro / Group، الحدود، الإضافات وبوابة الدفع داخل المنتج.',5,7,0,'planned',7),
('20000000-0000-4000-8000-000000000008','11111111-1111-4111-8111-111111111111','المشاركة والخصوصية','رابط عام قابل للإيقاف، واتساب يدوي، وإخفاء بيانات المالك.',4,7,16,'active',8),
('20000000-0000-4000-8000-000000000009','11111111-1111-4111-8111-111111111111','التنبيهات والبحث المحفوظ','التذكيرات، Saved Search، وتنبيهات فرص الباحثين Pro.',6,8,0,'planned',9),
('20000000-0000-4000-8000-000000000010','11111111-1111-4111-8111-111111111111','AI Matching','مطابقة الباحث بالعقار بدرجة توافق وسبب واضح ضمن الحصص.',7,9,0,'planned',10),
('20000000-0000-4000-8000-000000000011','11111111-1111-4111-8111-111111111111','التكامل والاختبار والإطلاق','اختبارات شاملة، إصلاحات، Release Candidate والتسليم.',8,10,0,'planned',11);
